<?php require_once "../config/database.php"; $id=(int)($_GET['id']??0); $s=$conn->prepare("SELECT * FROM patients WHERE id=?");$s->bind_param("i",$id);$s->execute();$p=$s->get_result()->fetch_assoc();if(!$p)die("Patient not found.");
if($_SERVER["REQUEST_METHOD"]==="POST"){$date_of_birth=$_POST['date_of_birth']!==''?$_POST['date_of_birth']:null;$s=$conn->prepare("UPDATE patients SET patient_number=?,first_name=?,last_name=?,gender=?,date_of_birth=?,phone=?,email=?,address=?,emergency_contact=?,emergency_phone=?,blood_group=? WHERE id=?");$s->bind_param("sssssssssssi",$_POST['patient_number'],$_POST['first_name'],$_POST['last_name'],$_POST['gender'],$date_of_birth,$_POST['phone'],$_POST['email'],$_POST['address'],$_POST['emergency_contact'],$_POST['emergency_phone'],$_POST['blood_group'],$id);if($s->execute()){header("Location:index.php");exit;}$error=$s->error;}?>
<!doctype html><html><head><title>Edit Patient</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><div class="container"><h1>Edit Patient</h1>
<?php if(!empty($error)): ?><p class="error"><?=htmlspecialchars($error)?></p><?php endif; ?><form method="post">
<label>Patient Number</label><input name="patient_number" value="<?=htmlspecialchars($p['patient_number'])?>" required><label>First Name</label><input name="first_name" value="<?=htmlspecialchars($p['first_name'])?>" required>
<label>Last Name</label><input name="last_name" value="<?=htmlspecialchars($p['last_name'])?>" required><label>Gender</label><select name="gender"><?php foreach(['Male','Female','Other'] as $g): ?><option <?=$p['gender']===$g?'selected':''?>><?=$g?></option><?php endforeach;?></select>
<label>Date of Birth</label><input type="date" name="date_of_birth" value="<?=htmlspecialchars($p['date_of_birth']??'')?>"><label>Phone</label><input name="phone" value="<?=htmlspecialchars($p['phone']??'')?>"><label>Email</label><input name="email" value="<?=htmlspecialchars($p['email']??'')?>">
<label>Address</label><input name="address" value="<?=htmlspecialchars($p['address']??'')?>"><label>Emergency Contact</label><input name="emergency_contact" value="<?=htmlspecialchars($p['emergency_contact']??'')?>"><label>Emergency Phone</label><input name="emergency_phone" value="<?=htmlspecialchars($p['emergency_phone']??'')?>"><label>Blood Group</label><select name="blood_group"><option value="">Select</option><?php $blood_groups=['A+','A-','B+','B-','AB+','AB-','O+','O-']; if($p['blood_group'] && !in_array($p['blood_group'],$blood_groups,true)): ?><option selected><?=htmlspecialchars($p['blood_group'])?></option><?php endif; foreach($blood_groups as $blood_group): ?><option value="<?=$blood_group?>" <?=$p['blood_group']===$blood_group?'selected':''?>><?=$blood_group?></option><?php endforeach; ?></select><button>Save Changes</button></form><a class="button secondary-button" href="view.php?id=<?=$id?>">View Patient</a> <a class="button secondary-button" href="../index.php">Home</a> <a class="button secondary-button" href="index.php">← Back</a></div></body></html>